head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > removeColumnFilterAll]<br/>DataList 모듈에 적용된 모든 필터/정렬 조건을 제거합니다.",
    "validation" : [
        "linkedDataList 모듈에 적용된 모든 필터/정렬 조건을 제거합니다.",
        "'Filter Condition' 과 'Sort Condition' 으로 적용된 필터/정렬은 제거하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }     

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createOrginalDataList();

    let strTarget = '';    
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:linkedDataList ' + strNameSpace + ' id="target1" bind="gdl_org">'
    strTarget += '<w2:condition type="filter"><![CDATA[cat1==ref("data:gdl_org.cat1")]]></w2:condition>'
    strTarget += '<w2:condition type="sort"><![CDATA[DESC("value")]]></w2:condition>'
    strTarget += '</w2:linkedDataList>'  

    $p.data.create(strTarget);

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();
}   



scwin.btn_setColumnFilter_onclick = function (e) {
    target1.setColumnFilter({type:"row", colIndex:"cat2", key:"A1", condition:"and"});

    scwin.btn_getAllFilteredData_onclick();
};



scwin.btn_removeColumnFilterAll_onclick = function (e) {
	target1.removeColumnFilterAll();

    scwin.btn_getAllFilteredData_onclick();
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("label", 0);

    scwin.btn_getAllFilteredData_onclick();
};



scwin.btn_getAllFilteredData_onclick = function (e) {
    let rtn = target1.getAllFilteredData();

	wf_body_bottom.getObj("scwin").setReturnValue("return: " + rtn);
};
